// One name/class scan per layer for the anchors this chunk needs.
def wanted = items.collectMany { it.verify + it.satisfy } as Set
def elements = [:]
['OA', 'SA', 'LA', 'PA', 'EPBS'].each { layer ->
    def iterator = api.layer(layer).eAllContents()
    while (iterator.hasNext()) {
        def element = iterator.next()
        def nameFeature = element.eClass().getEStructuralFeature('name')
        if (nameFeature == null) continue
        def key = layer + '|' + element.eClass().name + '|' + element.eGet(nameFeature)
        if (wanted.contains(key)) {
            assert !elements.containsKey(key): 'Ambiguous model anchor ' + key
            elements[key] = element
        }
    }
}
wanted.each { assert elements.containsKey(it): 'Missing model anchor ' + it }
def target = { id -> byId[id.startsWith('FSAE2027:') ? id : 'FSAE-2027-V1:' + id] }
items.each { item ->
    def requirement = byId[item.id]
    assert requirement != null: 'Missing item ' + item.id
    assert requirement.ownedRelations.isEmpty(): 'Item already traced, review it instead of replaying: ' + item.id
    item.derive.each { assert target(it) != null: 'Missing derive target ' + it }
}
def counts = [derive: 0, verify: 0, satisfy: 0]
api.batch('Trace submission items ' + 'des-2') {
    items.each { item ->
        def requirement = byId[item.id]
        item.derive.each { req.derive(requirement, target(it)); counts.derive++ }
        item.verify.each { req.verify(requirement, elements[it]); counts.verify++ }
        item.satisfy.each { req.satisfy(elements[it], requirement); counts.satisfy++ }
    }
}
log.info('Submission trace chunk ' + 'des-2' + ' applied: ' + counts)
return [chunk: 'des-2', items: items.size(), links: counts]
